      SUBROUTINE PLSGETCC     VALUES OF PARAMETERS DESCRIBING A PLASMA LENSCC ----------------------------------------------------------------------      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM1A.CIN'      INCLUDE 'ELM4A.CIN'      INCLUDE 'ELM4C.CIN'      INCLUDE 'ELM5A.CIN'      INCLUDE 'ELM6.CIN'      INCLUDE 'ELM15A.CIN'      INCLUDE 'ELM16B.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'ELM26B.CIN'      INCLUDE 'FLUSHC.CIN'      INCLUDE 'INDPAR.CIN'      INCLUDE 'IOUNIT.CIN'      INCLUDE 'XRAN.CIN'CC     LOCAL VARIABLESC      INTEGER          IADR, IAP, IB, IG, IK1      REAL             DATARC-------------------------------------------------------------------------------CC     MAGNET LENGTHC      IADR = I + 1      L = DATAR(IADR)      IF (PRAN34(1) .NE. 0.0) L = L + PRAN34(1)*XRAN(1)      L = L*UNITI(8)      LMAG = LCC     INDICES OF OTHER PARAMETERSC      IB = IPTOJ(2)      IAP = IPTOJ(3)      IG = IPTOJ(4)      IK1 = IPTOJ(5)      IF (IG .NE. 0) GO TO 10      IF (IK1 .NE. 0) GO TO 20      IF (IB .NE. 0) GO TO 5      KQ2 = 0.0      GO TO   40CC     MAGNETIC FIELD AND APERTUREC    5 IADR = I + IB      B = DATAR(IADR)      IF (PRAN34(2) .NE. 0.0) B = B + PRAN34(2)*XRAN(2)      B = B*UNITI(9)*RI/PREF      IF (IAP .NE. 0) THEN        IADR = I + IAP        AP = DATAR(IADR)      ELSE        WRITE (NOUT,9012) 9012   FORMAT (' *** ERROR *** PLASMA LENS APERTURE NOT GIVEN')        FLUSHL = .TRUE.        KQ2 = 0.0        AP = 0.0        GO TO 40      ENDIF      IF (AP .NE. 0.0) THEN        IF (PRAN34(3) .NE. 0.0) AP = AP + PRAN34(3)*XRAN(3)        AP = AP*UNITI(1)        IF (NORD1 .LT. 1) GO TO 40        KQ2 = B/(AP*RI)      ELSE        WRITE (NOUT,9011) 9011   FORMAT (' *** ERROR *** PLASMA LENS APERTURE SET TO ZERO')        FLUSHL = .TRUE.        KQ2 = 0.0      ENDIF      GO TO 40CC     GRADIENTC   10 IADR = I + IG      GRAD = DATAR(IADR)      IF (PRAN34(4) .NE. 0.0) GRAD = GRAD + PRAN34(4)*XRAN(4)      GRAD = GRAD*UNITI(9)*RI/(PREF*UNITI(1))      KQ2 = GRAD/RI      GO TO 40CC     NORMALIZED GRADIENT (MAD NOTATION)C   20 IADR = I + IK1      K1 = DATAR(IADR)      IF (PRAN34(5) .NE. 0.0) K1 = K1 + PRAN34(5)*XRAN(5)      KQ2 = K1/UNITI(8)**2C   40 RETURN      END